'use strict';
let workspaceQuery='',workspaceStatus='全部',parseSelection=null;
const baseNav={...names};Object.keys(names).forEach(k=>delete names[k]);Object.assign(names,{logcenter:'日志任务',parsing:'日志解析',logs:'日志阅读',issues:baseNav.issues,collect:baseNav.collect,source:baseNav.source,report:baseNav.report});
function logSources(){return state.issues.flatMap(i=>i.requests.map(r=>({issue:i,request:r,key:i.id+'/'+r.id}))).concat(LoganLogs.sources(state));}
function sourceStatus(r){if(r.status==='待解析')return '待解析';if(r.task)return r.status==='部分成功'?'部分可查':'解析完成';if(r.status==='解析失败')return '解析失败';if(r.status==='解析中')return '解析中';if(r.status==='上传失败')return '上传失败';if(['已取消','设备响应超时','推送失败','无可用日志','设备不支持'].includes(r.status))return r.status;return '等待文件';}
function selectedLogSource(){return logSources().find(x=>x.key===parseSelection)||logSources().at(-1);}
function workspaceHeading(title,description){return heading(title,description)+`<div class="notice">日志是独立入口，工单、回捞、源码和 AI 是关联能力。这里显示本地合成任务；未接入现有 Logan 的真实日志与解析接口。</div>`;}
function openParsing(key){parseSelection=key;go('parsing');}
function openSourceLogs(key){let x=logSources().find(s=>s.key===key);if(!x?.request.task)return toast('索引尚未发布，请先查看处理状态');state.active=x.issue.id;taskId=x.request.task;requestId=x.request.id;selected=4;query='';level='全部';contextMode=false;save();go('logs');}
function openSourceCollection(key){let x=logSources().find(s=>s.key===key);state.active=x.issue.id;requestId=x.request.id;save();go('collect');}
function downloadSourceSample(key){let x=logSources().find(s=>s.key===key);if(!x?.request.task)return toast('尚无可查正文');if(x.asset){let t=M.tasks(x.issue).find(t=>t.id===x.request.task);return file(t.id+'-parsed.jsonl',t.records.map(r=>JSON.stringify(r.fields||r)).join('\n'));}const kinds=x.request.files.filter(f=>f.status==='可查').map(f=>f.name.replace('.log',''));file(x.request.task+'-synthetic.log','合成演示正文；不是加密上传原文件\n'+records.filter(r=>kinds.includes(r.module==='Network'?'网络日志':'应用日志')).map(r=>r.time+' '+r.level+' '+r.module+' '+r.content).join('\n'));}
views.logcenter=function(){let sources=logSources(),ready=sources.filter(x=>x.request.task).length,failed=sources.filter(x=>['解析失败','上传失败'].includes(sourceStatus(x.request))).length;return workspaceHeading('日志任务','先找到日志、确认解析状态并阅读内容，再选择是否发起调查。')+`<div class="workspace-counts"><div><b>${sources.length}</b><span>本地任务来源</span></div><div><b>${ready}</b><span>已发布可查索引</span></div><div><b>${failed}</b><span>上传 / 解析失败</span></div></div><div class="panel"><div class="toolbar"><input aria-label="查找日志任务" placeholder="任务 / 设备 / 版本 / 工单" value="${esc(workspaceQuery)}" oninput="workspaceQuery=this.value;filterLogWorkspace()"><select aria-label="按解析状态筛选" onchange="workspaceStatus=this.value;filterLogWorkspace()">${['全部','解析完成','部分可查','解析中','解析失败'].map(s=>`<option ${s===workspaceStatus?'selected':''}>${s}</option>`).join('')}</select>${btn('查看解析状态',"go('parsing')")}${btn('发起日志回捞','collectForm()','primary')}</div><p class="muted">支持查看多个工单关联的日志。未解析成功也保留任务来源、文件结果和错误记录。</p><table><thead><tr><th>日志任务 / 来源</th><th>目标设备 / 版本</th><th>日志时间</th><th>状态</th><th>文件</th><th>操作</th></tr></thead><tbody>${sources.map(x=>{let i=x.issue,r=x.request,status=sourceStatus(r);return `<tr data-log-search="${esc((r.task||'')+' '+r.id+' '+r.device+' '+i.version+' '+i.id+' '+i.title)}" data-log-status="${status}"><td><b>${esc(r.task||'待生成索引')}</b><br><small>${r.id} · Native · ${esc(i.id)}</small></td><td>${esc(r.device)}<br><small>${esc(i.version)} / build ${esc(i.build)}</small></td><td><small>${esc(r.begin.replace('T',' '))}<br>至 ${esc(r.end.replace('T',' '))}</small></td><td>${badge(status,r.task?'ok':'warn')}</td><td>${r.files.length?`${r.files.filter(f=>f.status==='可查').length} / ${r.files.length} 可查`:'尚无文件'}</td><td><div class="table-actions">${btn('解析详情',`openParsing('${x.key}')`)}${btn('阅读日志',`openSourceLogs('${x.key}')`,'',!r.task)}${btn('下载样例',`downloadSourceSample('${x.key}')`,'',!r.task)}</div></td></tr>`;}).join('')}</tbody></table><div class="empty" id="log-workspace-empty" ${sources.length?'hidden':''}><h3>没有符合条件的日志任务</h3><p>调整任务、设备或状态条件；也可以先发起回捞。现有真实日志没有被导入或删除。</p></div></div><div class="panel"><h3>原有日志能力与当前原型的边界</h3><p>原 Logan 的 Native / Web 任务页、解析服务、索引查询、正文详情和下载实现均保留。当前原型准备的是 Native 合成场景，尚未补齐 Web 日志任务、直接上传导入和真实大日志操作的交互验收；这些仍计为需求缺口。</p></div>`;};
function filterLogWorkspace(){let count=0;document.querySelectorAll('[data-log-search]').forEach(row=>{row.hidden=!(row.dataset.logSearch.toLowerCase().includes(workspaceQuery.toLowerCase())&&(workspaceStatus==='全部'||row.dataset.logStatus===workspaceStatus));if(!row.hidden)count++;});$('#log-workspace-empty').hidden=count>0;}
views.parsing=function(){let sources=logSources(),x=selectedLogSource();return workspaceHeading('日志解析','保留文件来源、处理进度、失败原因和可查结果；不把推送接受等同于解析成功。')+`<div class="toolbar">${btn('← 日志任务',"go('logcenter')")}${x?`<label class="inline">选择处理记录 <select aria-label="选择日志解析记录" onchange="parseSelection=this.value;render()">${sources.map(s=>`<option value="${s.key}" ${s.key===x.key?'selected':''}>${s.request.task||s.request.id} · ${esc(s.request.device)} · ${sourceStatus(s.request)}</option>`).join('')}</select></label>`:''}</div>`+(!x?'<div class="panel empty"><h3>尚无日志处理记录</h3><p>先发起回捞，文件接收、解析和可查状态将在这里保留。</p></div>':parseView(x));};
function parseView(x){let i=x.issue,r=x.request,status=sourceStatus(r),completed=!!r.task,uploaded=r.files.some(f=>['已上传','可查','解析失败'].includes(f.status)),failed=r.status==='解析失败';return `<div class="panel"><div class="row"><div><h3>${esc(r.task||r.id)} · ${esc(r.device)}</h3><small>文件来源：日志回捞 ${r.id} · 关联工单 ${esc(i.id)}</small></div>${badge(status,completed?'ok':'warn')}</div><div class="facts"><span>日志范围<br><b>${esc(r.begin.replace('T',' '))} — ${esc(r.end.slice(11))}</b></span><span>应用版本 / 构建<br><b>${esc(i.version)} / ${esc(i.build)}</b></span><span>预算<br><b>${r.budget} MiB</b></span></div><div class="steps parsing-steps"><div class="step ${uploaded?'done':''}">文件接收 · ${uploaded?'已有文件':'等待中'}</div><div class="step ${completed?'done':failed?'fail':''}">解码与校验 · ${completed?'完成':failed?'失败':'尚未确认'}</div><div class="step ${completed?'done':''}">记录解析 · ${completed?'完成':'尚未发布'}</div><div class="step ${completed?'done':''}">索引发布 · ${completed?'可查':'未发布'}</div></div><p class="muted">解析内部阶段为交互示意；当前模拟只收到整体解析结果，没有真实阶段耗时或吞吐数据，不展示虚构性能指标。</p><div class="toolbar">${btn('阅读已解析日志',`openSourceLogs('${x.key}')`,'primary',!completed)}${btn('下载可查正文样例',`downloadSourceSample('${x.key}')`,'',!completed)}${btn('查看回捞进度',`openSourceCollection('${x.key}')`)}${btn('导出处理记录',`exportParseRecord('${x.key}')`)}</div></div><div class="grid"><div><div class="panel"><h3>文件处理结果</h3>${r.files.length?`<table><thead><tr><th>文件</th><th>大小（演示）</th><th>结果</th></tr></thead><tbody>${r.files.map(f=>`<tr><td>${esc(f.name)}</td><td>${f.size}</td><td>${badge(f.status,f.status==='可查'?'ok':'warn')}</td></tr>`).join('')}</tbody></table>`:'<p class="muted">尚未收到文件。可以查看回捞状态；此时不能进行正文搜索。</p>'}</div><div class="panel"><h3>处理记录与错误</h3><div class="timeline">${r.events.map(e=>`<p><small>${esc(e.time)}</small><br>${esc(e.text)}</p>`).join('')}</div>${failed?'<div class="notice">解析校验失败，未发布索引。原请求及错误记录保留；可在下方创建独立重新解析批次，也可回到采集流程重试设备回捞。</div>':''}</div></div><div><div class="panel"><h3>日志关联</h3><p>目标设备：${esc(r.device)}<br>来源请求：${r.id}<br>可查任务：${r.task||'未生成'}<br>关联工单：${esc(i.id)}</p>${btn('打开关联工单',`selectIssue('${i.id}')`)}</div><div class="panel"><h3>后续排查</h3><p>解析成功后，先阅读原始日志与上下文，再选择关联源码或将证据送入 AI 调查。</p>${btn('进入日志阅读',`openSourceLogs('${x.key}')`,'',!completed)}</div></div></div>`;}
function exportParseRecord(key){let x=logSources().find(s=>s.key===key),r=x.request;file(r.id+'-processing-demo.txt','本地合成处理记录，不是真实解析证据\n状态：'+sourceStatus(r)+'\n设备：'+r.device+'\n范围：'+r.begin+' — '+r.end+'\n'+r.events.map(e=>e.time+' '+e.text).join('\n'));}
const previousRenderWorkspace=render;render=function(){previousRenderWorkspace();if(page==='logcenter')filterLogWorkspace();};if(names[location.hash.slice(1)])page=location.hash.slice(1);render();
